import json
from typing import Any

from lfx.custom.custom_component.component import Component
from lfx.io import MessageTextInput, Output
from lfx.schema.data import Data


class RelativeVitalAnalyzer(Component):
    display_name = "Relative Vital Analyzer"
    description = (
        "Validate an IoT blood-pressure event and compare the current "
        "measurements with the user's personal baseline."
    )
    documentation = "https://docs.langflow.org/components-custom-components"
    icon = "Activity"
    name = "RelativeVitalAnalyzer"

    inputs = [
        MessageTextInput(
            name="event_json",
            display_name="IoT Event JSON",
            info="JSON event received from AI Agent Simulator.",
            required=True,
            tool_mode=False,
        ),
    ]

    outputs = [
        Output(
            display_name="Analysis",
            name="analysis",
            method="analyze_event",
        ),
    ]

    def _rejected(
        self,
        *,
        error_code: str,
        error_message: str,
        **details: Any,
    ) -> Data:
        result = {
            "status": "rejected",
            "error_code": error_code,
            "error_message": error_message,
            **details,
        }

        self.status = error_message
        return Data(value=result)

    def analyze_event(self) -> Data:
        raw_value = self.event_json

        try:
            payload: dict[str, Any] = json.loads(raw_value)
        except (json.JSONDecodeError, TypeError) as exc:
            return self._rejected(
                error_code="INVALID_JSON",
                error_message="Invalid IoT event JSON",
                detail=str(exc),
            )

        required_top_level = [
            "event_id",
            "event_type",
            "user_id",
            "display_name",
            "measurement",
            "baseline",
        ]

        missing_top_level = [
            field
            for field in required_top_level
            if payload.get(field) is None
        ]

        if missing_top_level:
            return self._rejected(
                error_code="MISSING_REQUIRED_FIELDS",
                error_message="Missing required event fields",
                missing_fields=missing_top_level,
            )

        if payload["event_type"] != "high_blood_pressure":
            return self._rejected(
                error_code="UNSUPPORTED_EVENT_TYPE",
                error_message="Unsupported event type",
                event_type=payload["event_type"],
            )

        measurement = payload.get("measurement") or {}
        baseline = payload.get("baseline") or {}

        required_measurements = [
            "systolic",
            "diastolic",
            "heart_rate",
        ]
        required_baseline = [
            "usual_systolic",
            "usual_diastolic",
            "resting_heart_rate",
        ]

        missing_measurements = [
            field
            for field in required_measurements
            if measurement.get(field) is None
        ]

        missing_baseline = [
            field
            for field in required_baseline
            if baseline.get(field) is None
        ]

        if missing_measurements or missing_baseline:
            return self._rejected(
                error_code="INCOMPLETE_VITAL_DATA",
                error_message="Incomplete vital data",
                missing_measurement_fields=missing_measurements,
                missing_baseline_fields=missing_baseline,
            )

        try:
            systolic = int(measurement["systolic"])
            diastolic = int(measurement["diastolic"])
            heart_rate = int(measurement["heart_rate"])

            usual_systolic = int(baseline["usual_systolic"])
            usual_diastolic = int(baseline["usual_diastolic"])
            resting_heart_rate = int(
                baseline["resting_heart_rate"]
            )
        except (TypeError, ValueError) as exc:
            return self._rejected(
                error_code="INVALID_VITAL_TYPE",
                error_message="Invalid vital value type",
                detail=str(exc),
            )

        # PoC technical validation ranges.
        # These reject obviously invalid device data and are not diagnostic rules.
        invalid_values: dict[str, int] = {}

        if not 40 <= systolic <= 300:
            invalid_values["systolic"] = systolic

        if not 30 <= diastolic <= 200:
            invalid_values["diastolic"] = diastolic

        if not 25 <= heart_rate <= 250:
            invalid_values["heart_rate"] = heart_rate

        if not 40 <= usual_systolic <= 300:
            invalid_values["usual_systolic"] = usual_systolic

        if not 30 <= usual_diastolic <= 200:
            invalid_values["usual_diastolic"] = usual_diastolic

        if not 25 <= resting_heart_rate <= 250:
            invalid_values["resting_heart_rate"] = resting_heart_rate

        if invalid_values:
            return self._rejected(
                error_code="VITAL_VALUE_OUT_OF_RANGE",
                error_message="Vital value is outside the accepted PoC range",
                invalid_values=invalid_values,
            )

        systolic_delta = systolic - usual_systolic
        diastolic_delta = diastolic - usual_diastolic
        heart_rate_delta = heart_rate - resting_heart_rate

        # PoC product rules, not universal medical thresholds.
        blood_pressure_above_baseline = (
            systolic_delta >= 10
            or diastolic_delta >= 10
        )

        if heart_rate_delta >= 15:
            heart_rate_state = "above_baseline"
        elif heart_rate_delta <= -15:
            heart_rate_state = "below_baseline"
        else:
            heart_rate_state = "near_baseline"

        if (
            blood_pressure_above_baseline
            and heart_rate_state == "above_baseline"
        ):
            scenario = "high_bp_high_relative_hr"
            next_action = "confirm_recent_activity"
            pending_question = "measurement_context"

        elif (
            blood_pressure_above_baseline
            and heart_rate_state == "near_baseline"
        ):
            scenario = "high_bp_near_relative_hr"
            next_action = "confirm_resting_measurement"
            pending_question = "measurement_context"

        elif (
            blood_pressure_above_baseline
            and heart_rate_state == "below_baseline"
        ):
            scenario = "high_bp_low_relative_hr"
            next_action = "confirm_resting_measurement"
            pending_question = "measurement_context"

        else:
            scenario = "no_significant_relative_change"
            next_action = "general_care"
            pending_question = "current_wellbeing"

        result = {
            "status": "accepted",
            "event_id": payload["event_id"],
            "trace_id": payload.get("trace_id"),
            "event_type": payload["event_type"],
            "user_id": payload["user_id"],
            "display_name": payload["display_name"],
            "device_id": payload.get("device_id"),
            "measurement": {
                "systolic": systolic,
                "diastolic": diastolic,
                "heart_rate": heart_rate,
                "measured_at": measurement.get("measured_at"),
            },
            "baseline": {
                "usual_systolic": usual_systolic,
                "usual_diastolic": usual_diastolic,
                "resting_heart_rate": resting_heart_rate,
            },
            "comparison": {
                "systolic_delta": systolic_delta,
                "diastolic_delta": diastolic_delta,
                "heart_rate_delta": heart_rate_delta,
                "blood_pressure_state": (
                    "above_baseline"
                    if blood_pressure_above_baseline
                    else "near_baseline"
                ),
                "heart_rate_state": heart_rate_state,
            },
            "scenario": scenario,
            "next_action": next_action,
            "pending_question": pending_question,
        }

        self.status = (
            f"{scenario} | "
            f"BP delta {systolic_delta}/{diastolic_delta} | "
            f"HR delta {heart_rate_delta}"
        )

        return Data(value=result)

import json
from typing import Any

from lfx.custom.custom_component.component import Component
from lfx.io import DataInput, MessageTextInput, Output
from lfx.schema.data import Data


class OutputContractFormatter(Component):
    display_name = "Output Contract Formatter"
    description = (
        "Combine model-generated content with deterministic analyzer state."
    )
    icon = "Braces"
    name = "OutputContractFormatter"

    inputs = [
        DataInput(
            name="structured_data",
            display_name="Structured Data",
            info="Structured response generated from the language model.",
            required=True,
        ),
        MessageTextInput(
            name="analysis_text",
            display_name="Analysis Text",
            info="Original accepted analyzer output from Accepted Event Router.",
            required=True,
        ),
    ]

    outputs = [
        Output(
            display_name="Formatted Output",
            name="formatted_output",
            method="format_output",
        ),
    ]

    def _unwrap_dict(self, source: Any) -> dict[str, Any]:
        """Unwrap Langflow Data and nested value wrappers."""
        if isinstance(source, Data):
            value = getattr(source, "value", None)

            if isinstance(value, dict):
                if isinstance(value.get("value"), dict):
                    return value["value"]
                return value

            data = getattr(source, "data", None)

            if isinstance(data, dict):
                if isinstance(data.get("value"), dict):
                    return data["value"]
                return data

        if isinstance(source, dict):
            if isinstance(source.get("value"), dict):
                return source["value"]
            return source

        return {}

    def _parse_analysis(self) -> dict[str, Any]:
        """Parse the complete analyzer JSON preserved by the router."""
        raw = self.analysis_text or ""

        try:
            parsed = json.loads(raw)
        except (TypeError, json.JSONDecodeError):
            return {}

        if isinstance(parsed, dict):
            if isinstance(parsed.get("value"), dict):
                return parsed["value"]
            return parsed

        return {}

    def format_output(self) -> Data:
        model_result = self._unwrap_dict(self.structured_data)
        analysis = self._parse_analysis()

        content = model_result.get("content")
        

        if not isinstance(content, str):
            content = ""

        content = content.strip()


        # Deterministic workflow fields come from the analyzer.
        result = {
            "status": (
                "success"
                if content
                else "fail"
            ),
            "scenario": analysis.get(
                "scenario",
                model_result.get("scenario", "unknown"),
            ),
            "content": content,
            "requires_reply": model_result.get(
                "requires_reply",
                True,
            ),
            "next_action": analysis.get(
                "next_action",
                model_result.get("next_action", "none"),
            ),
            "pending_question": analysis.get(
                "pending_question",
                model_result.get("pending_question", "none"),
            ),
            "validation_status": (
                model_result.get("validation_status", "pass")
                if content
                else "fail"
            ),
            "fallback_used": model_result.get(
                "fallback_used",
                False,
            ),
        }

        self.status = (
            f"{result['scenario']} | "
            f"{result['next_action']} | "
            f"{result['pending_question']}"
        )

        return Data(value=result)

import json
from typing import Any

from lfx.custom.custom_component.component import Component
from lfx.io import DataInput, Output
from lfx.schema.data import Data
from lfx.schema.message import Message


class AcceptedEventRouter(Component):
    display_name = "Accepted Event Router"
    description = (
        "Route analyzer Data while preserving the complete analysis result."
    )
    icon = "GitBranch"
    name = "AcceptedEventRouter"

    inputs = [
        DataInput(
            name="analysis_data",
            display_name="Analysis Data",
            info="Data output from Relative Vital Analyzer.",
            required=True,
        ),
    ]

    outputs = [
        Output(
            display_name="Accepted",
            name="accepted",
            method="route_accepted",
            group_outputs=True,
        ),
        Output(
            display_name="Rejected",
            name="rejected",
            method="route_rejected",
            group_outputs=True,
        ),
    ]

    def _get_value(self) -> dict[str, Any]:
        source = self.analysis_data

        if isinstance(source, Data):
            direct_value = getattr(source, "value", None)

            if isinstance(direct_value, dict):
                if isinstance(direct_value.get("value"), dict):
                    return direct_value["value"]
                return direct_value

            data_value = getattr(source, "data", None)

            if isinstance(data_value, dict):
                if isinstance(data_value.get("value"), dict):
                    return data_value["value"]
                return data_value

        if isinstance(source, dict):
            if isinstance(source.get("value"), dict):
                return source["value"]
            return source

        return {}

    def _to_message(self, value: dict[str, Any]) -> Message:
        return Message(
            text=json.dumps(
                {"value": value},
                ensure_ascii=False,
            ),
            sender="Machine",
            sender_name="System",
        )

    def route_accepted(self) -> Message:
        value = self._get_value()

        if value.get("status") != "accepted":
            self.stop("accepted")

        self.status = (
            f"Accepted: {value.get('scenario', 'unknown')}"
        )

        return self._to_message(value)

    def route_rejected(self) -> Message:
        value = self._get_value()

        if value.get("status") == "accepted":
            self.stop("rejected")

        self.status = (
            f"Rejected: {value.get('error_code', 'UNKNOWN_ERROR')}"
        )

        return self._to_message(value)
